#!/usr/bin/env bash
# One-off: regenerate why3 run shim from the CURRENT spec (root container), then
# run the full R2 verify loop.
set -euo pipefail
docker run --rm \
  -v /home/cc/formal-tools-build/src:/src:ro \
  -v /home/cc/formal-tools-build/out:/out \
  ft-builder:deb13 python3 - <<'PYEOF'
import re

spec = open("/src/portable/builders/tools/why3.sh", encoding="utf-8").read()
m = re.search(r"ft::make_shim '(.*?)'\n", spec, re.S)
shim_body = m.group(1)
shim = (
    "#!/bin/sh\n"
    "# generated by formal-tools portable builders — do not edit\n"
    'FT_ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)\n'
    'TOOL_DIR="$FT_ROOT/tools/why3"\n'
    + shim_body
    + "\n"
)
open("/out/tools/why3/run", "w", encoding="utf-8", newline="\n").write(shim)
print("SHIM_REGEN_OK bytes=", len(shim))
PYEOF
docker run --rm -v /home/cc/formal-tools-build/out:/out ft-builder:deb13 \
  chmod +x /out/tools/why3/run
cd /home/cc/formal-tools-build
bash src/portable/scripts/r2-verify-loop.sh
